<?php
namespace App\Repositories; use App\Core\Database;
final class ClientRepository extends BaseRepository{protected string $table='clients';public function all(int $limit=500):array{$limit=max(1,min(1000,$limit));$s=Database::pdo()->query("SELECT c.*,COALESCE((SELECT SUM(i.balance) FROM invoices i WHERE i.client_id=c.id AND i.status NOT IN ('void','cancelled')),0) live_balance FROM clients c WHERE c.deleted_at IS NULL ORDER BY c.id DESC LIMIT {$limit}");return $s->fetchAll();}public function findWithRelations(int $id):?array{$c=$this->find($id);if(!$c)return null;$pdo=Database::pdo();foreach(['businesses','contacts'] as $t){$s=$pdo->prepare("SELECT * FROM {$t} WHERE client_id=? ORDER BY id DESC");$s->execute([$id]);$c[$t]=$s->fetchAll();}$s=$pdo->prepare('SELECT * FROM client_comments WHERE client_id=? AND deleted_at IS NULL ORDER BY id DESC');$s->execute([$id]);$c['comments']=$s->fetchAll();$s=$pdo->prepare('SELECT cs.*,s.name service_name FROM client_services cs JOIN services s ON s.id=cs.service_id WHERE cs.client_id=? ORDER BY cs.id DESC');$s->execute([$id]);$c['services']=$s->fetchAll();return $c;}}
